import 'dart:io';
abstract class SellerRepository { Future<Map<String, dynamic>> dashboard(); Future<List<Map<String, dynamic>>> listings(); Future<Map<String, dynamic>> createListing(Map<String, dynamic> data); Future<Map<String, dynamic>> updateListing(int id, Map<String, dynamic> data); Future<void> deleteListing(int id); Future<Map<String, dynamic>> setListingStatus(int id, String status); Future<List<Map<String, dynamic>>> bookings(); Future<Map<String, dynamic>> updateBooking(int id, String status); Future<List<Map<String, dynamic>>> leads(); Future<Map<String, dynamic>> updateLead(int id, String status); Future<List<String>> uploadImages(List<File> images); Future<Map<String, dynamic>> account(); Future<Map<String, dynamic>> updateAccount(Map<String, dynamic> data); Future<List<Map<String, dynamic>>> notifications(); Future<void> markNotificationsRead(); }
